L["Someone %d"] = "Игрок %d"
L["switched off -- a press still casts what the fight froze"] = "Manners выключен -- нажатие все равно применит то, что заморозил бой"
L["switched off -- nothing armed, and the panel cannot go"] = "Manners выключен -- ничего не заряжено, а панель нельзя убрать"
